// src/services/contract/dynamicSdk.ts

export function generateRenstraftSdk(
  slug: string,
  isPublished: boolean,
): string {
  let runtimeUrl = (
    process.env.DYNAMIC_RUNTIME_PUBLIC_URL || "http://localhost:3000"
  ).replace(/\/+$/, "");

  // Kalau URL-nya belum ada /api/runtime di ujungnya, tambahin otomatis
  if (!runtimeUrl.endsWith("/api/runtime")) {
    runtimeUrl = `${runtimeUrl}/api/runtime`;
  }

  return `// /lib/renscraft.js
// AUTO-GENERATED BY SERVER. DO NOT EDIT THIS FILE.

const SLUG = "${slug}";
const BASE_URL = "${runtimeUrl}";
const IS_PUBLISHED = ${isPublished};


// Memory adapter untuk Sandpack Preview
const memoryDb = {};

async function apiRequest(collection, method, data, id) {
  const path = \`/\${SLUG}/collections/\${collection}/documents\${id ? '/' + id : ''}\`;
  const res = await fetch(BASE_URL + path, {
    method,
    headers: { "Content-Type": "application/json" },
    body: data ? JSON.stringify(data) : undefined,
  });
  
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || "Database error");
  }
  return res.json();
}

export const db = {
  collection: (name) => ({
    list: async (query = {}) => {
      if (!IS_PUBLISHED) {
        return { data: memoryDb[name] || [] };
      }
      const qs = new URLSearchParams(query).toString();
      const res = await fetch(\`\${BASE_URL}/\${SLUG}/collections/\${name}/documents?\${qs}\`);
      if (!res.ok) return { data: [] };
      return res.json();
    },
    create: async (data) => {
      if (!IS_PUBLISHED) {
        if (!memoryDb[name]) memoryDb[name] = [];
        const newDoc = { id: Date.now().toString(), ...data, createdAt: new Date().toISOString() };
        memoryDb[name].push(newDoc);
        return { ok: true, id: newDoc.id };
      }
      return apiRequest(name, "POST", data);
    },
    get: async (id) => {
      if (!IS_PUBLISHED) {
        const doc = (memoryDb[name] || []).find(d => d.id === id);
        return doc ? { data: doc } : { data: null };
      }
      return apiRequest(name, "GET", null, id);
    }
  })
};
`;
}
